return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce সম্পর্কে','Go to Plugin Search' => 'প্লাগইন অনুসন্ধানে যান','Activate %s' => '%s সক্রিয় করুন','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s এর</strong> জন্য <strong>%2$s</strong> ইনস্টল এবং সক্রিয় করা প্রয়োজন। <a href="%4$s">%3$s</a>','Enter your code here' => 'এখানে আপনার কোড লিখুন','Add %s' => '%s যোগ করুন','Remove' => 'অপসারণ','Order number and receipt will be sent to this email address.' => 'অর্ডার নম্বর এবং রসিদ এই ইমেল ঠিকানায় পাঠানো হবে।','Apartment, unit, building, floor, etc.' => 'অ্যাপার্টমেন্ট, ইউনিট, ভবন, মেঝে, ইত্যাদি।','Shipping phone' => 'শিপিং ফোন','Only used for shipping-related questions.' => 'শুধুমাত্র শিপিং-সম্পর্কিত প্রশ্নের জন্য ব্যবহৃত।','Single step' => 'একক পদক্ষেপ','Click to go to the order summary' => 'অর্ডার সারাংশে যেতে ক্লিক করুন','Cart total:' => 'মোট কার্ট:','Proceed to %s' => '%s এ যান','Proceed to contact' => 'যোগাযোগ করতে এগিয়ে যান','Proceed to shipping' => 'শিপিং শুরু করুন','Proceed to billing' => 'বিলিংয়ে এগিয়ে যান','Proceed to payment' => 'পেমেন্টে এগিয়ে যান','Shipping method' => 'শিপিং পদ্ধতি','Additional notes' => 'অতিরিক্ত নোট','Payment method' => 'পেমেন্ট পদ্ধতি','Step %1$s of %2$s' => '%2$s এর %1$s ধাপ','Change: %s' => 'পরিবর্তন: %s','Not selected yet.' => 'এখনও নির্বাচিত হয়নি।','Same as shipping address' => 'শিপিং ঠিকানার মতোই','Same as billing address' => 'বিলিং ঠিকানার মতোই','Order summary' => 'অর্ডারের সারাংশ','Edit cart' => 'কার্ট সম্পাদনা করুন','Did you mean %s?' => 'তুমি কি %s বলতে চাইছো?','Change email address to: {suggestion-value}' => 'ইমেল ঠিকানাটি এতে পরিবর্তন করুন: {suggestion-value}','This is a required field.' => 'এটি একটি প্রয়োজনীয় ক্ষেত্র।','This is not a valid email address.' => 'এটি একটি বৈধ ইমেল ঠিকানা নয়।','This field does not match the related field value.' => 'এই ক্ষেত্রটি সম্পর্কিত ক্ষেত্র মানের সাথে মেলে না।','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; CPF নম্বরটি অবৈধ।','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ নম্বর &quot;{cnpj_number}&quot; অবৈধ।','(Required)' => '(প্রয়োজনীয়)','Checkout Header - Desktop' => 'চেকআউট হেডার - ডেস্কটপ','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'বড় স্ক্রিনের জন্য চেকআউট হেডারে উইজেটগুলি প্রদর্শন করুন। শুধুমাত্র প্লাগইনের চেকআউট হেডার ব্যবহার করলেই প্রদর্শিত হবে।','Checkout Header - Mobile' => 'চেকআউট হেডার - মোবাইল','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'মোবাইল ডিভাইসের জন্য চেকআউট হেডারের নিচে উইজেটগুলি প্রদর্শন করুন। শুধুমাত্র প্লাগইনের চেকআউট হেডার ব্যবহার করলেই প্রদর্শিত হবে।','Checkout Sidebar' => 'চেকআউট সাইডবার','Display widgets on the checkout sidebar after the order summary.' => 'অর্ডার সারাংশের পরে চেকআউট সাইডবারে উইজেটগুলি প্রদর্শন করুন।','Checkout Order Summary' => 'চেকআউট অর্ডারের সারাংশ','Display widgets inside the order summary at the checkout page.' => 'চেকআউট পৃষ্ঠায় অর্ডার সারাংশের ভিতরে উইজেটগুলি প্রদর্শন করুন।','Checkout Below Place Order' => 'নিচে চেকআউট করুন অর্ডার দিন','Display widgets below the place order button at the checkout page.' => 'চেকআউট পৃষ্ঠায় অর্ডার দেওয়ার বোতামের নীচে উইজেটগুলি প্রদর্শন করুন।','Checkout Footer' => 'চেকআউট ফুটার','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'চেকআউট ফুটারে উইজেটগুলি প্রদর্শন করুন। শুধুমাত্র প্লাগইনের চেকআউট ফুটার ব্যবহার করলেই প্রদর্শিত হবে।','Classic' => 'ক্লাসিক','Boxed' => 'বক্সড','Split' => 'বিভক্ত','Minimalist' => 'মিনিমালিস্ট','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz এর ফ্লুইড চেকআউট এবং ডেলিভারি ডেট প্লাগইন','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>আমরা সনাক্ত করেছি যে আপনি CodeRockz এর WooCommerce (ফ্রি এবং প্রো) এর জন্য ডেলিভারি এবং পিকআপ তারিখের সময় প্লাগইনগুলি ব্যবহার করছেন। এই প্লাগইনগুলির সাথে ইন্টিগ্রেশন Fluid Checkout PRO তে স্থানান্তরিত করা হয়েছে।</p>','Upgrade to PRO' => 'PRO তে আপগ্রেড করুন','Fluid Checkout database updated successfully' => 'ফ্লুইড চেকআউট ডাটাবেস সফলভাবে আপডেট করা হয়েছে','The database changes where applied successfully.' => 'সফলভাবে প্রয়োগ করা হলে ডাটাবেস পরিবর্তন হয়।','Dismiss' => 'খারিজ করুন','Fluid Checkout database update' => 'ফ্লুইড চেকআউট ডাটাবেস আপডেট','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ডাটাবেসে কিছু পরিবর্তন প্রয়োজন। যেকোনো আপডেটের মতো, আমরা আপনাকে <strong>এগিয়ে যাওয়ার আগে আপনার ওয়েবসাইটের সম্পূর্ণ ব্যাকআপ নেওয়ার</strong> পরামর্শ দিচ্ছি।','Update database' => 'ডাটাবেস আপডেট করুন','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'ফ্লুইড চেকআউট ডিভি বিল্ডার চেকআউট লেআউটের সাথে সামঞ্জস্যপূর্ণ নয়।','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>ফ্লুইড চেকআউটের জন্য ক্লাসিক WooCommerce শর্টকোড-ভিত্তিক চেকআউট ফর্ম প্রয়োজন। চেকআউট পৃষ্ঠার চেহারা এবং অনুভূতি কাস্টমাইজ করার জন্য Divi Builder ব্যবহার করার সময়, চেকআউট পৃষ্ঠার প্রতিটি অংশের জন্য ক্লাসিক শর্টকোডগুলি Divi Builder থেকে কাস্টম উইজেট দিয়ে প্রতিস্থাপন করা হয়। এই কাস্টম উইজেটগুলি ফ্লুইড চেকআউটের সাথে সামঞ্জস্যপূর্ণ নয়।</p><p> অনুগ্রহ করে আপনার চেকআউট পৃষ্ঠাটি সম্পাদনা করুন, Divi Builder উইজেটগুলি <code>[woocommerce_checkout]</code> শর্টকোড ধারণকারী একটি টেক্সট উইজেট দিয়ে প্রতিস্থাপন করুন।</p>','Edit the checkout page' => 'চেকআউট পৃষ্ঠাটি সম্পাদনা করুন','Read the documentation.' => 'ডকুমেন্টেশনটি পড়ুন।','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'ফ্লুইড চেকআউট ব্যবহার করার সময় জার্মানাইজড প্রো মাল্টিস্টেপ চেকআউট বৈশিষ্ট্যটি অক্ষম করা প্রয়োজন।','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'ফ্লুইড চেকআউট ব্যবহার করার সময়, জার্মানাইজড প্রো প্লাগইনের মাল্টিস্টেপ বৈশিষ্ট্যটি অপ্রয়োজনীয় হয়ে পড়ে এবং <strong>নতুন অর্ডার প্রক্রিয়াকরণের সময় গুরুতর ত্রুটির</strong> কারণ হতে পারে। প্লাগইন সেটিংসে জার্মানাইজড প্রো মাল্টিস্টেপ চেকআউট বৈশিষ্ট্যটি অক্ষম করুন।','Go to Germanized settings' => 'জার্মানাইজড সেটিংসে যান।','Thanks for choosing Fluid Checkout!' => 'ফ্লুইড চেকআউট বেছে নেওয়ার জন্য ধন্যবাদ!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'তুমি অনেকদিন ধরে প্লাগইনটি ব্যবহার করছো। এখন পর্যন্ত এটা তোমার কেমন লেগেছে?<br> অনুগ্রহ করে আমাদের দ্রুত রেটিং দিন, আমরা প্রতিটি প্রতিক্রিয়ার জন্য কৃতজ্ঞ এবং এটি আমাদের প্লাগইনটি উন্নত করতে উৎসাহিত করে :)','Rate the plugin' => 'প্লাগইনটি রেট করুন','I need help!' => 'আমার সাহায্য দরকার!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Quadlayers-এর WooCommerce Checkout Manager-এর কিছু বৈশিষ্ট্য Fluid Checkout-এর সাথে ব্যবহার করার সময় প্রত্যাশা অনুযায়ী কাজ নাও করতে পারে। আরও তথ্য এবং বিকল্প সমাধানের জন্য <a href="%s">আমাদের ডকুমেন্টেশন</a> পড়ুন।','Read documentation' => 'ডকুমেন্টেশন পড়ুন','Don\'t show this again' => 'এটি আর দেখাবেন না','Fluid Checkout PRO' => 'Fluid Checkout PRO সম্পর্কে','More design templates' => 'আরও ডিজাইন টেমপ্লেট','Optimized cart page' => 'অপ্টিমাইজ করা কার্ট পৃষ্ঠা','Optimized order received / thank you page' => 'অপ্টিমাইজ করা অর্ডার গৃহীত হয়েছে / ধন্যবাদ পৃষ্ঠা','Edit cart contents at checkout page' => 'চেকআউট পৃষ্ঠায় কার্টের বিষয়বস্তু সম্পাদনা করুন','Account matching / user matching' => 'অ্যাকাউন্ট ম্যাচিং / ব্যবহারকারী ম্যাচিং','Trust symbols on the cart and thank you pages' => 'কার্ট এবং ধন্যবাদ পৃষ্ঠায় বিশ্বাসের প্রতীক','More positions for the coupon code on the checkout page' => 'চেকআউট পৃষ্ঠায় কুপন কোডের জন্য আরও অবস্থান','International phone numbers' => 'আন্তর্জাতিক ফোন নম্বর','Gift messages and packing slips' => 'উপহারের বার্তা এবং প্যাকিং স্লিপ','Local pickup and in-store collection' => 'স্থানীয় পিকআপ এবং দোকান থেকে সংগ্রহ','EU-VAT Assistant' => 'EU-VAT সহকারী','I already have it – Hide this offer' => 'আমার কাছে ইতিমধ্যেই আছে - এই অফারটি লুকান।','Activated' => 'সক্রিয়','Address book' => 'ঠিকানা বই','Select an image' => 'একটি ছবি নির্বাচন করুন','Cart layout' => 'কার্ট লেআউট','Cart optimizations' => 'কার্ট অপ্টিমাইজেশন','Enable cart page optimizations' => 'কার্ট পৃষ্ঠা অপ্টিমাইজেশন সক্ষম করুন','Header and footer template' => 'হেডার এবং ফুটার টেমপ্লেট','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'বিভ্রান্তিমুক্ত পৃষ্ঠার হেডার এবং ফুটার ব্যবহার করা হবে নাকি বর্তমানে সক্রিয় থিমের হেডার এবং ফুটার রাখা হবে তা নিয়ন্ত্রণ করে।','Distraction free header and footer' => 'বিক্ষেপমুক্ত হেডার এবং ফুটার','Theme\'s header and footer' => 'থিমের হেডার এবং ফুটার','Cart elements' => 'কার্ট উপাদান','Make the order summary stay visible on the cart page while scrolling' => 'স্ক্রোল করার সময় অর্ডারের সারাংশ কার্ট পৃষ্ঠায় দৃশ্যমান রাখুন','Coupon codes' => 'কুপন কোড','Hidden' => 'লুকানো','Before the cart items section' => 'কার্ট আইটেম বিভাগের আগে','Inside the cart items section' => 'কার্ট আইটেম বিভাগের ভিতরে','After the cart items section' => 'কার্ট আইটেম বিভাগের পরে','Before the shipping section' => 'শিপিং বিভাগের আগে','After the shipping section' => 'শিপিং বিভাগের পরে','Before the order summary' => 'অর্ডার সারাংশের আগে','Inside the order summary' => 'অর্ডারের সারাংশের ভিতরে','Before the order totals' => 'অর্ডারের মোট পরিমাণের আগে','After the order totals' => 'অর্ডারের মোট পরিমাণের পরে','After the order summary' => 'অর্ডার সারাংশের পরে','Shipping' => 'পরিবহন','Select position where to display the shipping costs and calculator on the cart page.' => 'কার্ট পৃষ্ঠায় শিপিং খরচ এবং ক্যালকুলেটর কোথায় প্রদর্শন করবেন তা নির্বাচন করুন।','Display as a cart section' => 'কার্ট বিভাগ হিসেবে প্রদর্শন করুন','Cross-sells' => 'ক্রস-সেলস','Select position where to display the cross-sells section on the cart page.' => 'কার্ট পৃষ্ঠায় ক্রস-সেলস বিভাগটি কোথায় প্রদর্শন করবেন তা নির্বাচন করুন।','Before the cart actions' => 'কার্ট অ্যাকশনের আগে','After the cart actions' => 'কার্ট অ্যাকশনের পরে','Layout of cross-sell items on the cart page.' => 'কার্ট পৃষ্ঠায় ক্রস-সেল আইটেমের লেআউট।','Optimized horizontal cross-sells layout' => 'অপ্টিমাইজ করা অনুভূমিক ক্রস-সেলস লেআউট','Theme\'s cross-sells layout' => 'থিমের ক্রস-সেলস লেআউট','Number of cross-sell items to display on the cart page' => 'কার্ট পৃষ্ঠায় প্রদর্শনের জন্য ক্রস-সেল আইটেমের সংখ্যা','Add widget areas to the cart page' => 'কার্ট পৃষ্ঠায় উইজেট এলাকা যোগ করুন','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'এই উইজেট এলাকাগুলি কার্ট পৃষ্ঠায় বিশ্বাসের প্রতীক এবং বিশ্বাসের ব্যাজ যোগ করতে ব্যবহৃত হয়।','Checkout' => 'চেকআউট','Checkout layout' => 'চেকআউট লেআউট','Design template' => 'ডিজাইন টেমপ্লেট','Dark mode' => 'ডার্ক মোড','Enable dark mode' => 'ডার্ক মোড চালু করুন','Logo image' => 'লোগোর ছবি','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'চেকআউট পৃষ্ঠার হেডারে প্রদর্শিত করার জন্য একটি ছবি বেছে নিন। শুধুমাত্র বিক্ষেপমুক্ত হেডার এবং ফুটার ব্যবহার করলেই প্রযোজ্য।','Header background color' => 'হেডারের পটভূমির রঙ','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'চেকআউট পৃষ্ঠার হেডারের জন্য একটি ব্যাকগ্রাউন্ড রঙ বেছে নিন। শুধুমাত্র ডিসট্রাকশন-মুক্ত হেডার এবং ফুটার ব্যবহার করলেই প্রযোজ্য।','HTML color value. ie: #f3f3f3' => 'HTML রঙের মান। অর্থাৎ: #f3f3f3','Page background color' => 'পৃষ্ঠার পটভূমির রঙ','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'চেকআউট পৃষ্ঠার জন্য একটি পটভূমির রঙ নির্বাচন করুন। <em>বডি</em> এলিমেন্টে রঙ প্রয়োগ করা হয়।','Footer background color' => 'পাদলেখের পটভূমির রঙ','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'চেকআউট পৃষ্ঠার ফুটারের জন্য একটি ব্যাকগ্রাউন্ড রঙ চয়ন করুন। শুধুমাত্র বিভ্রান্তিমুক্ত হেডার এবং ফুটার ব্যবহার করার সময় প্রযোজ্য।','Progress bar' => 'অগ্রগতি বার','Make the checkout progress bar stay visible while scrolling' => 'স্ক্রোল করার সময় চেকআউট প্রগ্রেস বারটি দৃশ্যমান রাখুন','Express checkout' => 'দ্রুত চেকআউট','Enable the express checkout section' => 'এক্সপ্রেস চেকআউট বিভাগটি সক্ষম করুন','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'সমর্থিত পেমেন্ট গেটওয়েগুলিতে এই বৈশিষ্ট্যটি সক্রিয় থাকলে চেকআউটের সময় এক্সপ্রেস চেকআউট বিভাগটি প্রদর্শন করে।','Display express checkout buttons in one line for larger screens' => 'বড় স্ক্রিনের জন্য এক লাইনে এক্সপ্রেস চেকআউট বোতামগুলি প্রদর্শন করুন','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'একটি সামঞ্জস্যপূর্ণ এক্সপ্রেস চেকআউট পেমেন্ট গেটওয়ে দিয়ে অর্থ প্রদানের সময় অতিরিক্ত চেকআউট প্রয়োজনীয় ক্ষেত্রগুলি উপেক্ষা করুন।','Make the order summary stay visible while scrolling' => 'স্ক্রোল করার সময় অর্ডারের সারাংশ দৃশ্যমান রাখুন','Choose a background color for the order summary section.' => 'অর্ডার সারাংশ বিভাগের জন্য একটি পটভূমির রঙ চয়ন করুন।','Highlight the order totals row in the order summary table' => 'অর্ডার সারাংশ টেবিলে অর্ডারের মোট সংখ্যার সারিটি হাইলাইট করুন।','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'অর্ডার সারাংশ বিভাগে হাইলাইট করা ব্যাকগ্রাউন্ড রঙ না থাকলে এটি সবচেয়ে কার্যকর। Fluid Checkout PRO ব্যবহার করার সময় কার্ট, অর্ডার রিসিভড এবং ভিউ অর্ডার পৃষ্ঠাগুলিতেও প্রযোজ্য হতে পারে।','Action link on the order summary at checkout.' => 'চেকআউটের সময় অর্ডারের সারাংশে অ্যাকশন লিঙ্ক।','Edit cart link' => 'কার্টের লিঙ্ক সম্পাদনা করুন','Cart items count' => 'কার্টে থাকা আইটেমের সংখ্যা','Link to shop page' => 'দোকানের পৃষ্ঠার লিঙ্ক','Cart items' => 'কার্ট আইটেম','Hide cart items errors at the checkout page' => 'চেকআউট পৃষ্ঠায় কার্ট আইটেমের ত্রুটি লুকান','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'চেকআউট পৃষ্ঠার উপরে কার্ট আইটেম ত্রুটি বার্তা প্রদর্শন করবেন না। ক্রয় সম্পূর্ণ করার জন্য চেকআউট ফর্ম জমা দেওয়ার সময়, এই ত্রুটি বার্তাগুলি সর্বদা প্রদর্শিত হবে।','Place order' => 'অর্ডার দিন','Define the position to display "Place order" and terms checkbox section.' => '&quot;অর্ডার দিন&quot; এবং শর্তাবলী চেকবক্স বিভাগটি প্রদর্শনের অবস্থান নির্ধারণ করুন।','Some options might not be compatible with some plugins and themes.' => 'কিছু বিকল্প কিছু প্লাগইন এবং থিমের সাথে সামঞ্জস্যপূর্ণ নাও হতে পারে।','Below the payment section' => 'পেমেন্ট বিভাগের নিচে','Below the order summary' => 'অর্ডারের সারাংশের নিচে','Both below the payment section and the order summary' => 'পেমেন্ট বিভাগের নীচে এবং অর্ডারের সারাংশ উভয়ই','Add widget areas to the checkout page' => 'চেকআউট পৃষ্ঠায় উইজেট এলাকা যোগ করুন','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'এই উইজেট এলাকাগুলি চেকআউট পৃষ্ঠায় বিশ্বাসের প্রতীক এবং বিশ্বাসের ব্যাজ যোগ করতে ব্যবহৃত হয়।','Display the coupon codes section title' => 'কুপন কোড বিভাগের শিরোনাম প্রদর্শন করুন','Select position where to display the coupon codes section on the checkout page.' => 'চেকআউট পৃষ্ঠায় কুপন কোড বিভাগটি কোথায় প্রদর্শন করবেন তা নির্বাচন করুন।','Before the checkout steps' => 'চেকআউট ধাপের আগে','As a substep before payment methods' => 'পেমেন্ট পদ্ধতির আগে একটি সাবস্টেপ হিসেবে','As a substep after payment methods' => 'পেমেন্ট পদ্ধতির পরে একটি সাবস্টেপ হিসেবে','Default button style' => 'ডিফল্ট বোতাম স্টাইল','"Add" link button' => '&quot;লিঙ্ক যোগ করুন&quot; বোতাম','Checkout fields' => 'চেকআউট ক্ষেত্র','Optional fields' => 'ঐচ্ছিক ক্ষেত্র','Hide optional fields behind a link button' => 'লিঙ্ক বোতামের পিছনে ঐচ্ছিক ক্ষেত্রগুলি লুকান','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'খোলা ইনপুট ক্ষেত্রের সংখ্যা কমাতে এই বিকল্পটি চেক করে রাখার পরামর্শ দেওয়া হচ্ছে, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">গবেষণাটি পড়ুন</a> ।','Do not hide "Address line 2" fields behind a link button' => 'লিঙ্ক বোতামের পিছনে &quot;ঠিকানা লাইন ২&quot; ক্ষেত্রগুলি লুকাবেন না।','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'যখন বেশিরভাগ গ্রাহকের &quot;ঠিকানা লাইন ২&quot; ফিল্ডের প্রয়োজন হয়, অথবা যখন সঠিক শিপিং ঠিকানা পাওয়া অত্যন্ত গুরুত্বপূর্ণ (যেমন, খাদ্য এবং অন্যান্য পচনশীল পণ্য সরবরাহের ক্ষেত্রে) তখনই এটি সুপারিশ করা হয়।','Billing address' => 'বিলিং ঠিকানা','Select position where to display the billing address section on the checkout page.' => 'চেকআউট পৃষ্ঠায় বিলিং ঠিকানা বিভাগটি কোথায় প্রদর্শন করবেন তা নির্বাচন করুন।','As a step before shipping' => 'শিপিংয়ের আগে একটি পদক্ষেপ হিসেবে','As a sub-step before the shipping address section' => 'শিপিং ঠিকানা বিভাগের আগে একটি উপ-পদক্ষেপ হিসেবে','As a sub-step after the shipping address section' => 'শিপিং ঠিকানা বিভাগের পরে একটি উপ-পদক্ষেপ হিসেবে','As a step after shipping' => 'শিপিংয়ের পরের ধাপ হিসেবে','As a sub-step before the payment section' => 'পেমেন্ট বিভাগের আগে একটি উপ-পদক্ষেপ হিসেবে','Force billing and shipping addresses to the same (single section)' => 'বিলিং এবং শিপিং ঠিকানা একই (একক বিভাগ) এ জোর করে রাখুন','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;শিপিং/বিলিং ঠিকানার মতো&quot; এর চেকবক্সটি ডিফল্টভাবে চেক করা আছে','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => '&quot;শিপিং ঠিকানার মতোই&quot; চেকবক্সটি ডিফল্টভাবে চেক করা অবস্থায় শুরু হবে যখন শিপিং ঠিকানা বিভাগটি প্রথমে প্রদর্শিত হবে।<br> &quot;বিলিং ঠিকানার মতোই&quot; চেকবক্সটি ডিফল্টভাবে চেক করা অবস্থায় শুরু হবে যখন বিলিং ঠিকানা বিভাগটি প্রথমে প্রদর্শিত হবে।<br> চেকআউটের সময় খোলা ইনপুট ক্ষেত্রের সংখ্যা উল্লেখযোগ্যভাবে হ্রাস করার জন্য এই বিকল্পটি চেক করে রাখা বাঞ্ছনীয়, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">গবেষণাটি পড়ুন</a> ।','Highlight the billing address section in the checkout form' => 'চেকআউট ফর্মের বিলিং ঠিকানা বিভাগটি হাইলাইট করুন।','Shipping address' => 'পাঠানোর ঠিকানা','Highlight the shipping address section in the checkout form' => 'চেকআউট ফর্মে শিপিং ঠিকানা বিভাগটি হাইলাইট করুন।','Shipping methods' => 'শিপিং পদ্ধতি','Choose in which position to display the shipping methods section.' => 'শিপিং পদ্ধতি বিভাগটি কোন অবস্থানে প্রদর্শন করবেন তা চয়ন করুন।','Before shipping address' => 'শিপিং ঠিকানার আগে','After shipping address' => 'শিপিং ঠিকানার পরে','Local pickup' => 'স্থানীয় পিকআপ','Removes shipping address section when a local pickup shipping method is selected.' => 'স্থানীয় পিকআপ শিপিং পদ্ধতি নির্বাচন করা হলে শিপিং ঠিকানা বিভাগটি সরিয়ে দেয়।','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'স্থানীয় পিকআপ শিপিং পদ্ধতি নির্বাচন করা হলে শিপিং ঠিকানাটিকে পিকআপ পয়েন্টের অবস্থান দিয়ে প্রতিস্থাপন করে।','Choose which address to save as the shipping address for local pickup orders.' => 'স্থানীয় পিকআপ অর্ডারের জন্য শিপিং ঠিকানা হিসেবে কোন ঠিকানাটি সংরক্ষণ করবেন তা বেছে নিন।','Save the selected pickup location' => 'নির্বাচিত পিকআপ লোকেশন সংরক্ষণ করুন','Save same as the billing address' => 'বিলিং ঠিকানার মতোই সংরক্ষণ করুন','Do not save any shipping address' => 'কোনও শিপিং ঠিকানা সংরক্ষণ করবেন না','Company name field for shipping address' => 'শিপিং ঠিকানার জন্য কোম্পানির নামের ক্ষেত্র','Change visibility for the company name field for the shipping address section on the checkout form.' => 'চেকআউট ফর্মের শিপিং ঠিকানা বিভাগের জন্য কোম্পানির নাম ক্ষেত্রের দৃশ্যমানতা পরিবর্তন করুন।','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'যদি ক্ষেত্রটি &quot;ঐচ্ছিক&quot; হিসাবে সেট করা থাকে, যা ডিফল্ট দৃশ্যমানতার অবস্থা, তাহলে অন্য প্লাগইনগুলিকে তাদের প্রয়োজনীয় পরিবর্তনগুলি প্রয়োগ করতে দেওয়ার জন্য কোনও পরিবর্তন প্রয়োগ করা হবে না।','Hidden (remove field)' => 'লুকানো (ক্ষেত্রটি সরান)','Optional' => 'ঐচ্ছিক','Required' => 'প্রয়োজনীয়','Add shipping phone field to the checkout form.' => 'চেকআউট ফর্মে শিপিং ফোন ফিল্ড যোগ করুন।','Choose in which step to display the shipping phone field.' => 'কোন ধাপে শিপিং ফোন ক্ষেত্রটি প্রদর্শন করবেন তা বেছে নিন।','Contact step' => 'যোগাযোগের ধাপ','Billing phone' => 'বিলিং ফোন','Add billing phone field to the checkout form.' => 'চেকআউট ফর্মে বিলিং ফোন ফিল্ড যোগ করুন।','Choose in which step to display the billing phone field.' => 'কোন ধাপে বিলিং ফোন ফিল্ডটি প্রদর্শন করবেন তা বেছে নিন।','Show country code beside the flag' => 'পতাকার পাশে দেশের কোড দেখান','Show an example of a valid phone number inside phone fields' => 'ফোন ফিল্ডের ভেতরে একটি বৈধ ফোন নম্বরের উদাহরণ দেখান','Do not change placeholders' => 'স্থানধারক পরিবর্তন করবেন না','Show if not defined' => 'সংজ্ঞায়িত না থাকলে দেখান','Always show' => 'সর্বদা দেখান','Order notes' => 'নোট অর্ডার করুন','Define the visibility of the additional order notes field.' => 'অতিরিক্ত অর্ডার নোট ক্ষেত্রের দৃশ্যমানতা নির্ধারণ করুন।','Gift options' => 'উপহারের বিকল্প','Allow customers to add a gift message and other gift related options to the order.' => 'গ্রাহকদের অর্ডারে একটি উপহারের বার্তা এবং অন্যান্য উপহার সম্পর্কিত বিকল্প যোগ করার অনুমতি দিন।','Display the gift message as part of the order details table instead of a separate section' => 'উপহারের বার্তাটি আলাদা বিভাগের পরিবর্তে অর্ডারের বিবরণ টেবিলের অংশ হিসেবে প্রদর্শন করুন।','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'এই বিকল্পটি অর্ডার নিশ্চিতকরণ পৃষ্ঠা (ধন্যবাদ পৃষ্ঠা) এবং অ্যাকাউন্ট পৃষ্ঠা, ইমেল এবং প্যাকিং স্লিপে অর্ডারের বিবরণকে প্রভাবিত করে।','Account matching' => 'অ্যাকাউন্ট ম্যাচিং','Enable the account matching feature' => 'অ্যাকাউন্ট ম্যাচিং বৈশিষ্ট্যটি সক্ষম করুন','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'গ্রাহকের যোগাযোগের বিবরণ সহ একটি অ্যাকাউন্ট ইতিমধ্যেই বিদ্যমান থাকলে অতিথি গ্রাহকের অর্ডারগুলি তাদের বিদ্যমান অ্যাকাউন্টের সাথে সংযুক্ত করুন।','Display message when an account exists with the email address provided' => 'প্রদত্ত ইমেল ঠিকানা সহ কোনও অ্যাকাউন্ট বিদ্যমান থাকলে বার্তা প্রদর্শন করুন','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'অ্যাকাউন্ট তৈরির ক্ষেত্রগুলিকে একটি বিজ্ঞপ্তি এবং লগ ইন করার বিকল্প দিয়ে প্রতিস্থাপন করে। কিছু প্রসঙ্গে, গ্রাহকদের গোপনীয়তা রক্ষা করার জন্য এই বিকল্পটি অক্ষম রাখার পরামর্শ দেওয়া হতে পারে।','Dashboard' => 'ড্যাশবোর্ড','Integrations' => 'ইন্টিগ্রেশন','License keys' => 'লাইসেন্স কী','Visit our website for more information about our plugins and add-ons.' => 'আমাদের প্লাগইন এবং অ্যাড-অন সম্পর্কে আরও তথ্যের জন্য আমাদের ওয়েবসাইট দেখুন।','Order pay page' => 'অর্ডার পেমেন্ট পৃষ্ঠা','Order pay' => 'অর্ডার পে','Enable order pay page optimizations' => 'অর্ডার পে পৃষ্ঠা অপ্টিমাইজেশন সক্ষম করুন','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'গ্রাহকের কাছ থেকে পেমেন্ট মুলতুবি থাকা বিদ্যমান অর্ডারগুলির জন্য অর্ডার পে পৃষ্ঠার লেআউট পরিবর্তন করে।','Add widget areas to the order pay page' => 'অর্ডার পেমেন্ট পৃষ্ঠায় উইজেট এলাকা যোগ করুন','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'এই উইজেট এলাকাগুলি অর্ডার পে পৃষ্ঠায় বিশ্বাসের প্রতীক এবং বিশ্বাসের ব্যাজ যোগ করতে ব্যবহৃত হয়।','Thank you page & order details layout' => 'ধন্যবাদ পৃষ্ঠা এবং অর্ডারের বিবরণ লেআউট','Order details optimizations' => 'অর্ডারের বিবরণ অপ্টিমাইজেশন','Enable thank you page and order details optimizations' => 'ধন্যবাদ পৃষ্ঠা এবং অর্ডারের বিবরণ অপ্টিমাইজেশন সক্ষম করুন','Changes the layout of order details on the thank you page and account pages.' => 'ধন্যবাদ পৃষ্ঠা এবং অ্যাকাউন্ট পৃষ্ঠাগুলিতে অর্ডারের বিবরণের বিন্যাস পরিবর্তন করে।','Enable order details customizations on email notifications' => 'ইমেল বিজ্ঞপ্তিতে অর্ডারের বিবরণ কাস্টমাইজেশন সক্ষম করুন','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ইমেল বিজ্ঞপ্তিগুলিতে নতুন বিভাগ প্রদর্শন করুন এবং বিভাগের ক্রম পরিবর্তন করুন। ইমেল বিজ্ঞপ্তিগুলিতে অর্ডারের বিবরণের ধরণ অপরিবর্তিত রয়েছে।','Thank you page' => 'ধন্যবাদ পাতা','These options affect the thank you page, also known as order received or order confirmation pages.' => 'এই বিকল্পগুলি ধন্যবাদ পৃষ্ঠাকে প্রভাবিত করে, যা অর্ডার প্রাপ্ত পৃষ্ঠা বা অর্ডার নিশ্চিতকরণ পৃষ্ঠা নামেও পরিচিত।','Order details layout' => 'অর্ডারের বিবরণের লেআউট','Display the order details with wide layout on the thank you page' => 'ধন্যবাদ পৃষ্ঠায় প্রশস্ত লেআউট সহ অর্ডারের বিবরণ প্রদর্শন করুন।','Add widget areas to the thank you page' => 'ধন্যবাদ পৃষ্ঠায় উইজেট এলাকা যোগ করুন','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'এই উইজেট এলাকাগুলি ধন্যবাদ পৃষ্ঠায় বিশ্বাসের প্রতীক এবং বিশ্বাসের ব্যাজ যোগ করতে ব্যবহৃত হয়।','Order actions' => 'অর্ডার অ্যাকশন','Choose in which position to display the order actions.' => 'অর্ডার অ্যাকশনগুলি কোন অবস্থানে 